UPDATE runtime_operations SET status=CASE WHEN status='delivering' AND EXISTS(SELECT 1 FROM runtime_delivery_units WHERE operation_id=?1 AND attempt=?2 AND status='unknown') THEN 'delivery_unknown' WHEN status='delivering' AND delivered_artifact_count>0 THEN 'delivery_partial' WHEN status='delivering' AND planned_artifact_count IS NULL THEN 'delivery_unknown' WHEN cancel_requested=1 THEN 'cancelled' WHEN attempt>=max_attempts THEN 'failed' ELSE 'queued' END,available_at=CASE WHEN (status='running' OR (status='delivering' AND delivered_artifact_count=0 AND planned_artifact_count IS NOT NULL AND NOT EXISTS(SELECT 1 FROM runtime_delivery_units WHERE operation_id=?1 AND attempt=?2 AND status='unknown'))) AND cancel_requested=0 AND attempt<max_attempts THEN CAST(unixepoch('subsec') * 1000000 AS INTEGER)+(retry_delay_secs*1000000) ELSE available_at END,worker_id=NULL,lease_token=NULL,lease_expires_at=NULL,progress_percent=NULL,progress_stage=NULL,updated_at=CAST(unixepoch('subsec') * 1000000 AS INTEGER) WHERE id=?1 AND attempt=?2 AND status IN ('running','delivering') AND lease_expires_at<=CAST(unixepoch('subsec') * 1000000 AS INTEGER);